// Build cover_html for PDFMonkey (markup-only).
// Adds a debug overlay when defaults.debug === true.
// Provides both <img> and background-image fallbacks.

const j = $input.first().json || {};
const cfg = j.CONFIG || {};
const r2 = cfg.r2 || {};
const defaults = cfg.defaults || {};

const runStamp = j.runStamp || new Date().toISOString();
const assetBase = defaults?.trimIn?.assetBase || '';
const r2PublicBase = (r2.publicBase || '').replace(/\/$/, '');
const debug = !!defaults?.debug;

function isUrl(s){ return typeof s === 'string' && /^https?:\/\//i.test(s); }
function toAssetUrl(path){
  if (!path) return undefined;
  if (isUrl(path)) return path;
  const clean = String(path).replace(/^\/+/, '');
  const base = r2PublicBase || assetBase;
  if (!base) return clean;
  return base.replace(/\/$/, '') + '/' + clean;
}

const orderId = j.orderId || j.amazonOrderId || 'unknown';

// Preferred refs
let coverRef =
  j.coverImageUrl ||
  (Array.isArray(j.coverImageUrls) && j.coverImageUrls[0]) ||
  j.coverPngR2Key ||
  j.pngGeneration?.coverSpreadImage ||
  j.pngGeneration?.coverPngR2Key;

// Deterministic fallback
if (!coverRef) {
  coverRef = `book-mvp-simple-adventure/orders/${orderId}/preview-images/cover-spread.png`;
}

let coverUrl = toAssetUrl(coverRef);
if (coverUrl) {
  coverUrl += (coverUrl.includes('?') ? '&' : '?') + 'v=' + encodeURIComponent(runStamp);
}

// Build robust markup (no <style>; CSS lives in template head)
const debugBadge = debug
  ? `<div style="position:absolute;z-index:2;top:10px;left:12px;padding:6px 10px;font:700 20px/1.1 system-ui, -apple-system, Segoe UI, Roboto, Arial;color:#111;background:#FFD700;opacity:.9;border-radius:6px">HELLO COVER</div>`
  : '';

const imgTag = coverUrl
  ? `<img class="bg" src="${coverUrl}" alt="" width="5203" height="2625" />`
  : ''; // if URL is missing, we’ll rely on base64 (see Step 3)

const bgDiv = coverUrl
  ? `<div class="bg no-object-fit" style="background-image:url('${coverUrl}');"></div>`
  : '';

const html =
`<section class="page">
  ${debugBadge}
  ${imgTag}
  ${bgDiv}
</section>`;

return [{
  json: {
    ...j,
    cover_html: html,
    coverPdfFilename: j.coverPdfFilename || `cover_${orderId}.pdf`,
    coverDebug: { orderId, coverRef, coverUrl, r2PublicBase, assetBase }
  }
}];

// Prepare cover document payload for PDFMonkey
// Requires the PDFMonkey template to render:  {{ cover_html | raw }}  in the body.

const d = $input.first().json || {};

const DEFAULT_COVER_TEMPLATE_ID = 'D52F14C8-BBC3-4058-929F-195DFC707E75';
const tpl = d.CONFIG?.pdfMonkey?.coverTemplateId || DEFAULT_COVER_TEMPLATE_ID;

if (!tpl) throw new Error('Missing PDFMonkey coverTemplateId for W4 cover.');
if (!d.cover_html) throw new Error('Missing cover_html for W4 cover PDF payload.');

const filename = d.coverPdfFilename || `cover_${d.orderId || d.amazonOrderId || 'unknown'}.pdf`;

return [
  {
    json: {
      ...d,
      coverDocument: {
        document_template_id: tpl,
        status: 'pending',
        meta: { _filename: filename },
        payload: {
          cover_html: d.cover_html
        }
      }
    }
  }
];

// Merge the PDFMonkey cover response with preserved workflow context
const httpResp = $input.first().json || {};
let ctx = {};
try { ctx = ($items('Build Cover HTML', 0, $runIndex)?.[0]?.json) || {}; } catch {}
if (!ctx.orderId && !ctx.amazonOrderId) {
  try { ctx = ($items('Validate & Normalize W4 Input', 0, $runIndex)?.[0]?.json) || ctx; } catch {}
}

const docObj = httpResp.document || httpResp.data || httpResp;
return [{
  json: {
    ...ctx,
    coverDocument: docObj
  }
}];

// Poll PDFMonkey until the cover PDF document is processed

// Input from previous node (Wait -> Reattach Cover Context (PDFM))
const base = $input.item?.json || $input.first()?.json || {};

// Prefer the explicit coverDocument we attached earlier.
// Fallbacks handle other possible shapes if needed.
const src =
  base.coverDocument ||
  base.data ||
  base.document ||
  base;

const docId = src.id || src.data?.id;

if (!docId) {
  // Helpful debug if something is off:
  // console.log('Poll Cover DEBUG base:', JSON.stringify(base, null, 2));
  throw new Error('PDFMonkey cover create response missing id');
}

const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const http = this.helpers.httpRequest;

// Use the same key style as the working interior poller.
// (Safe here because you're already hardcoding in W4; swap to CONFIG if desired.)
const AUTH_HEADER = {
  Authorization: 'Bearer 2zpxHdmsse2ECXgVVtVR',
};

let status = src.status || 'queued';
let downloadUrl = src.download_url || src.file_url || null;
let attempts = 0;

async function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

while (attempts < 30) {
  if (status === 'success' && downloadUrl) break;

  const resp = await http({
    method: 'GET',
    url: `${apiBase}${docId}`,
    json: true,
    headers: AUTH_HEADER,
  });

  const d = resp.data || resp.document || resp;

  status = d.status;
  downloadUrl = d.download_url || d.file_url || downloadUrl;

  if (status === 'error' || status === 'failure') {
    throw new Error(`PDFMonkey reported error status for cover PDF: ${status}`);
  }

  if (status === 'success' && downloadUrl) break;

  attempts++;
  await sleep(1800 + Math.floor(Math.random() * 600));
}

if (status !== 'success' || !downloadUrl) {
  throw new Error(`PDFMonkey cover PDF not ready after polling (status=${status})`);
}

// Preserve full context & append cover-specific fields
const ctx = $input.item?.json || $input.first()?.json || {};

return {
  json: {
    ...ctx,
    pdfMonkeyCoverDocumentId: docId,
    coverPdfDownloadUrl: downloadUrl,
  },
};

/**
 * Prepare Cover PDF Metadata for Merge
 */
function latest(node) {
  try { return ($items(node, 0, $runIndex)?.[0]?.json) || null; } catch { return null; }
}

const s3Out = $input.first()?.json || {};

const ctx =
  latest('Poll Cover PDFMonkey until ready') ||
  latest('Reattach Cover Context (PDFM)') ||
  latest('Build Cover HTML') ||
  latest('Validate & Normalize W4 Input') ||
  s3Out ||
  {};

const orderId = ctx.orderId || ctx.amazonOrderId || null;
const pdfFilename = ctx.coverPdfFilename || (orderId ? `cover_${orderId}.pdf` : null);
const pdfR2Key = ctx.coverPdfR2Key || (orderId && pdfFilename
  ? `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`
  : null);

if (!orderId || !pdfFilename || !pdfR2Key) {
  throw new Error(`Missing required cover PDF metadata: orderId=${orderId}, coverPdfFilename=${pdfFilename}, coverPdfR2Key=${pdfR2Key}`);
}

return [{
  json: {
    ...ctx,
    ...s3Out,
    coverPdfComplete: true,
    coverPdfUploadedAt: new Date().toISOString()
  }
}];

// Build pages_html for PDFMonkey at 8.75×8.75 in (bleed) from pageImageUrls
const j = $input.first().json || {};
const pages = Array.isArray(j.pageImageUrls) ? j.pageImageUrls : [];
if (pages.length === 0) throw new Error('No pageImageUrls to build pages_html');

const css = `
  <style>
    @page { size: 8.75in 8.75in; margin: 0; }
    html, body { margin:0; padding:0; }
    .page { width:8.75in; height:8.75in; page-break-after: always; }
    .bg { width:100%; height:100%; object-fit: cover; display:block; }
  </style>
`;

const pagesHtml = pages.map(url => {
  return `<section class="page"><img class="bg" src="${url}" alt="" /></section>`;
}).join('\n');

// Preserve upstream context and attach pages_html at top-level
const ctx = $input.first().json || {};
return [{
  json: {
    ...ctx,
    pages_html: `${css}\n${pagesHtml}`
  }
}];

const d = $input.first().json;
const tpl = d.CONFIG?.pdfMonkey?.templateId;
if (!tpl || tpl === 'REPLACE_WITH_PDFMONKEY_TEMPLATE_ID') {
  throw new Error('Missing PDFMonkey templateId in Config (W4). Please set CONFIG.pdfMonkey.templateId');
}
return [{
  json: {
    ...d,
    document: {
      document_template_id: tpl,
      status: 'pending',
      meta: { _filename: d.pdfFilename },
      payload: { pages_html: d.pages_html }
    }
  }
}];

const createResp = $input.first().json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;
if (!docId) throw new Error('PDFMonkey create response missing id');

const http = this.helpers.httpRequest;
const token = $json.CONFIG?.pdfMonkey?.token; if (!token) { throw new Error('Missing PDFMonkey token in CONFIG'); }
const AUTH_HEADER = { Authorization: `Bearer ${token}` };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;
async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 20) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method:'GET', url:`https://api.pdfmonkey.io/api/v1/documents/${docId}`, json:true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++; const delay = Math.min(6000, 2000 * (1 + attempts/3)); await sleep(delay);
}
if (status !== 'success' || !downloadUrl) throw new Error(`PDF not ready (status=${status})`);

const orderId = $json.orderId;
const pdfFilename = $json.pdfFilename || `interior_${orderId}.pdf`;
const pdfR2Key = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;
return [{ json: { ...$json, pdfMonkeyDocumentId: docId, pdfDownloadUrl: downloadUrl, pdfR2Key } }];

/**
 * Prepare PDF Metadata for Merge — resilient to S3 node dropping context
 */
function latest(node) {
  try { return ($items(node, 0, $runIndex)?.[0]?.json) || null; } catch { return null; }
}

const s3Out = $input.first()?.json || {};

// Reattach context from earlier nodes (first hit wins)
const ctx =
  latest('Poll PDFMonkey until ready') ||
  latest('Reattach Context (PDFM)') ||
  latest('Build Pages HTML (8.75in)') ||
  latest('Validate & Normalize W4 Input') ||
  s3Out || {};

const orderId     = ctx.orderId || null;
const pdfFilename = ctx.pdfFilename || (orderId ? `interior_${orderId}.pdf` : null);
const pdfR2Key    = ctx.pdfR2Key || (orderId && pdfFilename
                    ? `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`
                    : null);

if (!orderId || !pdfFilename || !pdfR2Key) {
  throw new Error(`Missing required PDF metadata: orderId=${orderId}, pdfFilename=${pdfFilename}, pdfR2Key=${pdfR2Key}`);
}

return [{
  json: {
    ...ctx,           // full upstream context (orderId, pdfR2Key, etc.)
    ...s3Out,         // anything S3 returned
    pdfComplete: true,
    pdfUploadedAt: new Date().toISOString()
  }
}];

// Merge the PDFMonkey response with the preserved workflow context
const httpResp = $input.first().json || {};
let ctx = {};
try { ctx = ($items('Build Pages HTML (8.75in)1', 0, $runIndex)?.[0]?.json) || {}; } catch {}
if (!ctx.orderId) {
  try { ctx = ($items('Validate & Normalize W4 Input', 0, $runIndex)?.[0]?.json) || ctx; } catch {}
}

// Keep the top-level shape that Poll node expects (document/data)
const docObj = httpResp.document || httpResp.data || httpResp;
return [{
  json: {
    ...ctx,
    document: docObj
  }
}];
